import React, { useEffect, useRef, useState } from "react";
import {
  Bell,
  Search,
  User
} from "lucide-react";

import { Link, useLocation } from "react-router-dom";

export default function StaffNavbar() {

  const location = useLocation();

  const [openSearch, setOpenSearch] = useState(false);
  const [openNotif, setOpenNotif] = useState(false);
  const [openAccount, setOpenAccount] = useState(false);

  const [search, setSearch] = useState("");
  const [products, setProducts] = useState([]);

  const [notifications, setNotifications] = useState([]);

  const searchRef = useRef(null);
  const notifRef = useRef(null);
  const accountRef = useRef(null);

  /* =========================
     FETCH PRODUCTS
  ========================= */
  useEffect(() => {
    fetch("http://localhost/GitHub/Capstone--Development/customer/api_products.php?action=list")
      .then(res => res.json())
      .then(data => {
        if (Array.isArray(data)) setProducts(data);
      })
      .catch(() => setProducts([]));
  }, []);

  /* =========================
     FETCH NOTIFICATIONS (ORDERS)
  ========================= */
  const fetchNotifications = () => {
    fetch("http://localhost/GitHub/Capstone--Development/staff/api_orders.php")
      .then(res => res.json())
      .then(data => {
        if (Array.isArray(data)) {

          const notif = data
            .filter(o =>
              o.status === "Pending" ||
              o.status === "Preparing"
            )
            .slice(0, 5);

          setNotifications(notif);

        }
      })
      .catch(() => setNotifications([]));
  };

  useEffect(() => {
    fetchNotifications();

    const interval = setInterval(() => {
      fetchNotifications();
    }, 5000);

    return () => clearInterval(interval);
  }, []);

  /* =========================
     CLOSE DROPDOWNS
  ========================= */
  useEffect(() => {
    const handleOutside = (e) => {
      if (searchRef.current && !searchRef.current.contains(e.target)) setOpenSearch(false);
      if (notifRef.current && !notifRef.current.contains(e.target)) setOpenNotif(false);
      if (accountRef.current && !accountRef.current.contains(e.target)) setOpenAccount(false);
    };

    document.addEventListener("mousedown", handleOutside);
    return () => document.removeEventListener("mousedown", handleOutside);
  }, []);

  const filteredProducts = products.filter(p =>
    p.name?.toLowerCase().includes(search.toLowerCase())
  );

  const handleLogout = () => {
    window.location.href = "http://localhost/GitHub/Capstone--Development/staff_login.php";
  };

  /* =========================
     NAV LINKS
  ========================= */
  const navs = [
    { name: "Dashboard", path: "/pastry_system/staff" },
    { name: "Orders", path: "/pastry_system/staff/orders" },
    { name: "Products", path: "/pastry_system/staff/products" },
    { name: "Customers", path: "/pastry_system/staff/customers" }
  ];

  return (

    <nav className="fixed top-0 left-0 w-full z-[99999] bg-white/90 backdrop-blur-xl border-b border-gray-100 px-6 xl:px-10 py-5">

      <div className="flex items-center justify-between">

        {/* LEFT */}
        <div className="flex items-center gap-14">

          <Link to="/pastry_system/staff" className="flex items-center gap-4">

            <img
              src="http://localhost/GitHub/Capstone--Development/uploads/logo.jpg"
              alt="Logo"
              className="h-14 w-auto object-contain"
            />

            <div>
              <h1 className="text-[28px] font-bold italic text-black leading-none">
                Pastry <span className="text-[#d4af37]">Project</span>
              </h1>
              <p className="text-[8px] uppercase tracking-[0.35em] text-gray-400 mt-1">
                staff management panel
              </p>
            </div>

          </Link>

          {/* NAV LINKS */}
          <div className="hidden lg:flex items-center gap-10">

            {navs.map(nav => (

              <Link
                key={nav.path}
                to={nav.path}
                className={`text-[10px] uppercase tracking-[0.3em] transition ${
                  location.pathname === nav.path
                    ? "text-black font-semibold"
                    : "text-gray-400 hover:text-black"
                }`}
              >
                {nav.name}
              </Link>

            ))}

          </div>

        </div>

        {/* RIGHT */}
        <div className="flex items-center gap-4">

          {/* SEARCH */}
          <button
            onClick={() => setOpenSearch(!openSearch)}
            className="w-12 h-12 rounded-full hover:bg-gray-100 flex items-center justify-center"
          >
            <Search size={20} />
          </button>

          {/* NOTIFICATIONS */}
          <div className="relative">

            <button
              onClick={() => setOpenNotif(!openNotif)}
              className="w-12 h-12 rounded-full hover:bg-gray-100 flex items-center justify-center relative"
            >
              <Bell size={20} />

              {notifications.length > 0 && (
                <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] w-5 h-5 flex items-center justify-center rounded-full">
                  {notifications.length}
                </span>
              )}

            </button>

            {/* DROPDOWN */}
            {openNotif && (
              <div
                ref={notifRef}
                className="absolute right-0 mt-3 w-80 bg-white shadow-xl rounded-xl border border-gray-100 p-4"
              >

                <h3 className="font-bold text-sm mb-3">
                  Notifications
                </h3>

                {notifications.length === 0 ? (
                  <p className="text-gray-400 text-sm">
                    No new orders
                  </p>
                ) : (

                  <div className="space-y-2 max-h-60 overflow-y-auto">

                    {notifications.map(n => (

                      <div
                        key={n.id}
                        className="p-3 bg-gray-50 hover:bg-gray-100 rounded-lg cursor-pointer"
                        onClick={() => {
                          window.location.href = "/pastry_system/staff/orders";
                        }}
                      >
                        <p className="text-sm font-semibold">
                          Order #{n.id}
                        </p>

                        <p className="text-xs text-gray-500">
                          {n.status} • ₱{Number(n.total).toLocaleString()}
                        </p>

                      </div>

                    ))}

                  </div>

                )}

              </div>
            )}

          </div>

          {/* USER */}
          <button
            onClick={() => setOpenAccount(!openAccount)}
            className="w-12 h-12 rounded-full bg-gray-100 flex items-center justify-center"
          >
            <User size={20} />
          </button>

        </div>

      </div>

    </nav>

  );

}
